import { InvitationShape } from '@agoric/zoe/src/typeGuards.js';
import { E } from '@endo/far';
import { M } from '@endo/patterns';
import { prepareChainHubAdmin } from '../exos/chain-hub-admin.js';
import { AnyNatAmountShape } from '../typeGuards.js';
import { withOrchestration } from '../utils/start-helper.js';
import { registerChainsAndAssets } from '../utils/chain-hub-helper.js';
import {
  makeNobleAccount as makeNobleAccountFlow,
  sendIt,
} from './send-anywhere.flows.js';
import * as sharedFlows from './shared.flows.js';

/**
 * @import {Remote, Vow} from '@agoric/vow';
 * @import {Zone} from '@agoric/zone';
 * @import {OrchestrationPowers, OrchestrationTools} from '../utils/start-helper.js';
 * @import {CosmosChainInfo, Denom, DenomDetail} from '@agoric/orchestration';
 * @import {ZCF} from '@agoric/zoe';
 * @import {Marshaller} from '@agoric/internal/src/lib-chainStorage.js';
 * @import {StorageNode} from '@agoric/internal/src/lib-chainStorage.js';
 */

export const SingleNatAmountRecord = M.and(
  M.recordOf(M.string(), AnyNatAmountShape, {
    numPropertiesLimit: 1,
  }),
  M.not(harden({})),
);
harden(SingleNatAmountRecord);

/**
 * Send assets currently in an ERTP purse to an account on another chain. This
 * currently supports IBC and CCTP transfers. It could eventually support other
 * protocols, like Axelar GMP or IBC Eureka.
 *
 * Orchestration contract to be wrapped by withOrchestration for Zoe
 *
 * @param {ZCF} zcf
 * @param {OrchestrationPowers & {
 *   assetInfo?: [Denom, DenomDetail & { brandKey?: string }][];
 *   chainInfo?: Record<string, CosmosChainInfo>;
 *   marshaller: Remote<Marshaller>;
 *   storageNode: Remote<StorageNode>;
 * }} privateArgs
 * @param {Zone} zone
 * @param {OrchestrationTools} tools
 */
export const contract = async (
  zcf,
  privateArgs,
  zone,
  { chainHub, orchestrate, vowTools, zoeTools },
) => {
  const creatorFacet = prepareChainHubAdmin(zone, chainHub);

  // UNTIL https://github.com/Agoric/agoric-sdk/issues/9066
  const logNode = E(privateArgs.storageNode).makeChildNode('log');
  /** @type {(msg: string) => Vow<void>} */
  const log = msg => vowTools.watch(E(logNode).setValue(msg));

  const makeLocalAccount = orchestrate(
    'makeLocalAccount',
    {},
    sharedFlows.makeLocalAccount,
  );
  const makeNobleAccount = orchestrate(
    'makeNobleAccountFlow',
    {},
    makeNobleAccountFlow,
  );

  const { brands } = zcf.getTerms();

  /**
   * ensure ChainHub is populated before trying to use it in flows
   */
  registerChainsAndAssets(
    chainHub,
    zcf.getTerms().brands,
    privateArgs.chainInfo,
    privateArgs.assetInfo,
  );
  /**
   * Set up a shared local account for use in async-flow functions. Typically,
   * exo initState functions need to resolve synchronously, but `makeOnce`
   * allows us to provide a Promise. When using this inside a flow, we must
   * await it to ensure the account is available for use.
   *
   * @type {any} sharedLocalAccountP expects a Promise but this is a vow UNTIL
   *   https://github.com/Agoric/agoric-sdk/issues/9822
   */
  const sharedLocalAccountP = zone.makeOnce('localAccount', () =>
    makeLocalAccount(),
  );
  // UNTIL https://github.com/Agoric/agoric-sdk/issues/9822.
  /** @type {any} nobleAccountP */
  const nobleAccountP = zone.makeOnce('nobleAccount', () => makeNobleAccount());
  // orchestrate uses the names on orchestrationFns to do a "prepare" of the associated behavior
  const sendAnywhere = orchestrate(
    'sendAnywhere',
    {
      log,
      chainHub,
      sharedLocalAccountP,
      nobleAccountP,
      USDC: brands.USDC,
      zoeTools,
    },
    sendIt,
  );

  const publicFacet = zone.exo(
    'Send PF',
    M.interface('Send PF', {
      makeSendInvitation: M.callWhen().returns(InvitationShape),
    }),
    {
      makeSendInvitation() {
        return zcf.makeInvitation(
          sendAnywhere,
          'send',
          undefined,
          M.splitRecord({ give: SingleNatAmountRecord }),
        );
      },
    },
  );

  return { publicFacet, creatorFacet };
};
harden(contract);

export const start = withOrchestration(contract, { publishAccountInfo: true });
harden(start);
import { NonNullish } from '@agoric/internal';
import { Fail, makeError, q } from '@endo/errors';
import { M, mustMatch } from '@endo/patterns';

/**
 * @import {GuestInterface, GuestOf} from '@agoric/async-flow';
 * @import {Invitation, ZCF, ZCFSeat} from '@agoric/zoe';
 * @import {Brand} from '@agoric/ertp';
 * @import {Vow} from '@agoric/vow';
 * @import {LocalOrchestrationAccountKit} from '../exos/local-orchestration-account.js';
 * @import {ZoeTools} from '../utils/zoe-tools.js';
 * @import {Orchestrator, OrchestrationFlow, LocalAccountMethods, ChainHub, ChainInfo} from '../types.js';
 * @import {AccountIdArg} from '../orchestration-api.js';
 * @import {CosmosOrchestrationAccountKit} from '../exos/cosmos-orchestration-account.js';
 */

const { entries } = Object;

// in guest file (the orchestration functions)
// the second argument is all the endowments provided

/**
 * @satisfies {OrchestrationFlow}
 * @param {Orchestrator} orch
 */
export const makeNobleAccount = async orch => {
  const nobleChain = await orch.getChain('noble');
  return nobleChain.makeAccount();
};
harden(makeNobleAccount);

const denomForBrand = async (orch, brand) => {
  const agoric = await orch.getChain('agoric');
  const assets = await agoric.getVBankAssetInfo();
  const { denom } = NonNullish(
    assets.find(a => a.brand === brand),
    `${brand} not registered in ChainHub`,
  );
  return denom;
};

/**
 * @satisfies {OrchestrationFlow}
 * @param {Orchestrator} orch
 * @param {object} ctx
 * @param {GuestInterface<ChainHub>} ctx.chainHub
 * @param {Promise<GuestInterface<LocalOrchestrationAccountKit['holder']>>} ctx.sharedLocalAccountP
 * @param {Promise<GuestInterface<CosmosOrchestrationAccountKit['holder']>>} ctx.nobleAccountP
 * @param {GuestInterface<ZoeTools>} ctx.zoeTools
 * @param {GuestOf<(msg: string) => Vow<void>>} ctx.log
 * @param {Brand} ctx.USDC
 * @param {ZCFSeat} seat
 * @param {{ chainName: string; destAddr: string }} offerArgs
 */
export const sendIt = async (
  orch,
  {
    chainHub,
    sharedLocalAccountP,
    log,
    nobleAccountP,
    USDC,
    zoeTools: { localTransfer, withdrawToSeat },
  },
  seat,
  offerArgs,
) => {
  mustMatch(offerArgs, harden({ chainName: M.scalar(), destAddr: M.string() }));
  const { chainName, destAddr } = offerArgs;
  // NOTE the proposal shape ensures that the `give` is a single asset
  const { give } = seat.getProposal();
  const [[_kw, amt]] = entries(give);
  void log(`sending {${amt.value}} from ${chainName} to ${destAddr}`);
  const denom = await denomForBrand(orch, amt.brand);

  /** @type {ChainInfo} */
  const info = await chainHub.getChainInfo(chainName);

  /**
   * @type {any} XXX methods returning vows
   *   https://github.com/Agoric/agoric-sdk/issues/9822
   */
  const sharedLocalAccount = await sharedLocalAccountP;

  /**
   * Helper function to recover if IBC Transfer fails
   *
   * @param {Error} e
   */
  const recoverFailedTransfer = async e => {
    await withdrawToSeat(sharedLocalAccount, seat, give);
    const errorMsg = `IBC Transfer failed ${q(e)}`;
    void log(`ERROR: ${errorMsg}`);
    seat.fail(errorMsg);
    throw makeError(errorMsg);
  };

  if (info.namespace === 'cosmos') {
    const { chainId } = info;
    assert(typeof chainId === 'string', 'bad chainId');

    const [_a, _o, connection] = await chainHub.getChainsAndConnection(
      'agoric',
      chainName,
    );

    connection.counterparty || Fail`No IBC connection to ${chainName}`;

    void log(`got info for chain: ${chainName} ${chainId}`);

    await localTransfer(seat, sharedLocalAccount, give);
    void log(`completed transfer to localAccount`);

    try {
      await sharedLocalAccount.transfer(
        {
          value: destAddr,
          encoding: 'bech32',
          chainId,
        },
        { denom, value: amt.value },
      );
      void log(`completed transfer to ${destAddr}`);
    } catch (e) {
      return recoverFailedTransfer(e);
    }
  } else if (amt.brand === USDC && 'cctpDestinationDomain' in info) {
    const nobleAccount = await nobleAccountP;
    const nobleAddr = nobleAccount.getAddress();
    const denomAmt = { denom, value: amt.value };
    try {
      await sharedLocalAccount.transfer(nobleAddr, denomAmt);
    } catch (e) {
      return recoverFailedTransfer(e);
    }
    void log('assets are now on noble');
    const destAccountId = /** @type {const} */ (
      `${info.namespace}:${info.reference}:${destAddr}`
    );
    try {
      await nobleAccount.depositForBurn(destAccountId, denomAmt);
    } catch (e) {
      try {
        // transfer back to agoric contract account if depositForBurn is not accepted by noble chain
        const lcaAddress = await sharedLocalAccount.getAddress();
        await nobleAccount.transfer(lcaAddress, denomAmt);
      } catch (err) {
        const errorMsg = `IBC Transfer from Noble back to LocalAccount failed: ${q(err)}`;
        void log(`🚨 contract upgrade required to recover funds: ${errorMsg}`);
        seat.fail(errorMsg);
        throw makeError(errorMsg);
      }
      return recoverFailedTransfer(e);
    }
  } else {
    Fail`There is currently support only for IBC and USDC transfers`;
  }

  seat.exit();
  void log(`transfer complete, seat exited`);
};
harden(sendIt);
import { prepareAsyncFlowTools } from '@agoric/async-flow';
import { wrapRemoteMarshaller } from '@agoric/internal/src/marshal/wrap-marshaller.js';
import { prepareVowTools } from '@agoric/vow';
import { prepareRecorderKitMakers } from '@agoric/zoe/src/contractSupport/recorder.js';
import { makeDurableZone } from '@agoric/zone/durable.js';
import { makeChainHub } from '../exos/chain-hub.js';
import { prepareCosmosOrchestrationAccount } from '../exos/cosmos-orchestration-account.js';
import { prepareLocalChainFacade } from '../exos/local-chain-facade.js';
import { prepareLocalOrchestrationAccountKit } from '../exos/local-orchestration-account.js';
import { prepareProgressTracker } from './progress.js';
import { prepareOrchestrator } from '../exos/orchestrator.js';
import { prepareRemoteChainFacade } from '../exos/remote-chain-facade.js';
import { makeOrchestrationFacade } from '../facade.js';
import { makeZoeTools } from './zoe-tools.js';
import { makeZcfTools } from './zcf-tools.js';

/**
 * @import {ERemote} from '@agoric/internal';
 * @import {Marshaller, StorageNode} from '@agoric/internal/src/lib-chainStorage.js';
 * @import {EMarshaller} from '@agoric/internal/src/marshal/wrap-marshaller.js';
 * @import {LocalChain} from '@agoric/vats/src/localchain.js';
 * @import {TimerService} from '@agoric/time';
 * @import {Baggage} from '@agoric/vat-data';
 * @import {NameHub} from '@agoric/vats';
 * @import {Remote} from '@agoric/vow';
 * @import {Zone} from '@agoric/zone';
 * @import {Pattern} from '@endo/patterns';
 * @import {CosmosInterchainService} from '../exos/exo-interfaces.js';
 * @import {ZCF} from '@agoric/zoe';
 */

/**
 * @typedef {{
 *   localchain: Remote<LocalChain>;
 *   orchestrationService: Remote<CosmosInterchainService>;
 *   storageNode?: Remote<StorageNode>;
 *   timerService: Remote<TimerService>;
 *   agoricNames: Remote<NameHub>;
 * }} OrchestrationPowers
 */

/**
 * @typedef {object} WithOrchestrationOpts
 * @property {boolean} [publishAccountInfo] - Controls whether account
 *   information (address, channel identifiers for ICAs) should be automatically
 *   published to vstorage
 * @property {Pattern} [chainInfoValueShape] - Overrides the default valueShape
 *   for ChainHub's `chainInfos: MapStore`. Intended to support a legacy version
 *   of ChainHub for FastUSDC.
 */

/**
 * Helper that a contract start function can use to set up the objects needed
 * for orchestration.
 *
 * TODO strip problematic operations from ZCF (e.g., getPayouts)
 *
 * @param {ZCF} zcf
 * @param {Baggage} baggage
 * @param {OrchestrationPowers} remotePowers
 * @param {Remote<Marshaller>} remoteMarshaller
 * @param {object} [opts]
 * @param {WithOrchestrationOpts['chainInfoValueShape']} [opts.chainInfoValueShape]
 * @internal
 */
export const provideOrchestration = (
  zcf,
  baggage,
  remotePowers,
  remoteMarshaller,
  opts = {},
) => {
  // separate zones
  const zones = (() => {
    const zone = makeDurableZone(baggage);
    return {
      /** system names for async flow */
      asyncFlow: zone.subZone('asyncFlow'),
      /** system names for orchestration implementation */
      orchestration: zone.subZone('orchestration'),
      /** system names for chainHub */
      chainHub: zone.subZone('chainHub'),
      /** system names for vows */
      vows: zone.subZone('vows'),
      /** contract-provided names, and subzones */
      contract: zone.subZone('contract'),
    };
  })();

  const { agoricNames, timerService, localchain } = remotePowers;

  const vowTools = prepareVowTools(zones.vows);

  const chainHub = makeChainHub(zones.chainHub, agoricNames, vowTools, {
    chainInfoValueShape: opts.chainInfoValueShape,
  });

  const zoeTools = makeZoeTools(zcf, vowTools);

  const zcfTools = makeZcfTools(zcf, vowTools);

  const cachingMarshaller = wrapRemoteMarshaller(remoteMarshaller);

  const { makeRecorderKit } = prepareRecorderKitMakers(
    baggage,
    cachingMarshaller,
  );
  const makeProgressTracker = prepareProgressTracker(zones.orchestration, {
    vowTools,
  });
  const makeLocalOrchestrationAccountKit = prepareLocalOrchestrationAccountKit(
    zones.orchestration,
    {
      makeProgressTracker,
      makeRecorderKit,
      zcf,
      timerService,
      vowTools,
      chainHub,
      localchain,
      zoeTools,
    },
  );

  const asyncFlowTools = prepareAsyncFlowTools(zones.asyncFlow, {
    vowTools,
  });

  const makeCosmosOrchestrationAccount = prepareCosmosOrchestrationAccount(
    zones.orchestration,
    {
      chainHub,
      makeProgressTracker,
      makeRecorderKit,
      timerService,
      vowTools,
      zcf,
    },
  );

  const makeRemoteChainFacade = prepareRemoteChainFacade(zones.orchestration, {
    makeCosmosOrchestrationAccount,
    orchestration: remotePowers.orchestrationService,
    storageNode: remotePowers.storageNode,
    timer: remotePowers.timerService,
    vowTools,
  });

  const makeLocalChainFacade = prepareLocalChainFacade(zones.orchestration, {
    makeLocalOrchestrationAccountKit,
    localchain: remotePowers.localchain,
    // FIXME what path?
    storageNode: remotePowers.storageNode,
    agoricNames,
    orchestration: remotePowers.orchestrationService,
    timer: remotePowers.timerService,
    vowTools,
  });

  const makeOrchestrator = prepareOrchestrator(zones.orchestration, {
    chainHub,
    makeLocalChainFacade,
    makeRemoteChainFacade,
    vowTools,
  });

  /**
   * Create orchestrate functions in a specific zone, instead of the default
   * `contract.orchestration` zone. This is used for modules that add their own
   * orchestration functions (e.g., a Portfolio with orchestration flows for
   * continuing offers)
   *
   * @param {Zone} zone
   */
  const makeOrchestrateKit = zone =>
    makeOrchestrationFacade({
      zone,
      zcf,
      makeOrchestrator,
      asyncFlowTools,
      vowTools,
      ...remotePowers,
    });

  // Create orchestrate functions for the default `contract.orchestration` zone
  const defaultOrchestrateKit = makeOrchestrateKit(
    zones.contract.subZone('orchestration'),
  );

  zcf.setTestJig(() => ({
    baggage,
    chainHub,
  }));

  return {
    ...defaultOrchestrateKit,
    makeOrchestrateKit,
    baggage,
    cachingMarshaller,
    chainHub,
    vowTools,
    asyncFlowTools,
    zcfTools,
    zoeTools,
    zone: zones.contract,
  };
};
harden(provideOrchestration);

/** @typedef {Omit<ReturnType<typeof provideOrchestration>, 'zone'>} OrchestrationTools */

/**
 * Simplifies contract functions for Orchestration by wrapping a simpler
 * function with all the tools it needs in order to use Orchestration.
 *
 * @example
 *
 * ```js
 * const contract = (zcf, privateArgs, zone, tools) => { ... };
 * export const start = withOrchestration(contract);
 * ```
 *
 * @template {Record<string, unknown>} CT
 * @template {OrchestrationPowers & {
 *   marshaller: Remote<Marshaller>;
 * }} PA
 * @template R
 * @param {(
 *   zcf: ZCF<CT>,
 *   privateArgs: PA,
 *   zone: Zone,
 *   tools: OrchestrationTools,
 * ) => Promise<R>} contractFn
 * @param {WithOrchestrationOpts} [opts]
 * @returns {(zcf: ZCF<CT>, privateArgs: PA, baggage: Baggage) => Promise<R>} a
 *   Zoe start function
 */
export const withOrchestration =
  (contractFn, opts) => async (zcf, privateArgs, baggage) => {
    const { marshaller: remoteMarshaller, ...allOrchPowers } = privateArgs;
    const { storageNode: _, ...requiredOrchPowers } = allOrchPowers;
    const { publishAccountInfo, chainInfoValueShape } = opts ?? {};

    const { zone, ...tools } = provideOrchestration(
      zcf,
      baggage,
      publishAccountInfo ? allOrchPowers : requiredOrchPowers,
      remoteMarshaller,
      { chainInfoValueShape },
    );
    const [startResult] = await Promise.all([
      contractFn(zcf, privateArgs, zone, tools),
      // Make sure that any errors in async-flow awake abort contract start
      tools.asyncFlowTools.allWokenP,
    ]);
    return startResult;
  };
harden(withOrchestration);
/**
 * @file Helper functions for transferring payments between a LocalChainAccount
 *   and a ZCFSeat.
 *
 *   Maintainers: This exists as an endowment for orchestrated async-flows so we
 *   can make use of E and promises. The logic for recovering partial failures
 *   is also an added convenience for developers.
 *
 *   Functions are written using `asVow` and non-resumable promises as we expect
 *   each invocation to resolve promptly - there are no timers or interchain
 *   network calls.
 *
 *   A promise resolved promptly is currently safe from being severed by an
 *   upgrade because we only trigger vat upgrades as the result of network
 *   input.
 */

import { makeError, q, Fail } from '@endo/errors';
import { depositToSeat } from '@agoric/zoe/src/contractSupport/index.js';
import { E } from '@endo/far';
import { makeTracer } from '@agoric/internal';

const trace = makeTracer('ZoeTools');

const { assign, keys, values } = Object;

/**
 * @import {HostOf} from '@agoric/async-flow';
 * @import {InvitationMakers} from '@agoric/smart-wallet/src/types.js';
 * @import {ResolvedPublicTopic} from '@agoric/zoe/src/contractSupport/topics.js';
 * @import {VowTools} from '@agoric/vow';
 * @import {LocalAccountMethods} from '../types.js';
 * @import {ZCFSeat} from '@agoric/zoe';
 * @import {AmountKeywordRecord} from '@agoric/zoe';
 * @import {ZCF} from '@agoric/zoe';
 * @import {Payment} from '@agoric/ertp';
 */

/**
 * @typedef {{
 *   invitationMakers: InvitationMakers;
 *   publicSubscribers: Record<string, ResolvedPublicTopic<any>>;
 * }} ResolvedContinuingOfferResult
 *
 * @see {ContinuingOfferResult}
 */

/**
 * @typedef {(
 *   srcSeat: ZCFSeat,
 *   localAccount: LocalAccountMethods,
 *   amounts: AmountKeywordRecord,
 * ) => Promise<void>} LocalTransfer
 */

/**
 * @typedef {(
 *   localAccount: LocalAccountMethods,
 *   destSeat: ZCFSeat,
 *   amounts: AmountKeywordRecord,
 * ) => Promise<void>} WithdrawToSeat
 */

/**
 * @param {ZCF} zcf
 * @param {VowTools} vowTools
 */
export const makeZoeTools = (zcf, { when, allVows, allSettled, asVow }) => {
  /**
   * Transfer the `amounts` from `srcSeat` to `localAccount`. If any of the
   * deposits fail, everything will be rolled back to the `srcSeat`. Supports
   * multiple items in the `amounts` {@link AmountKeywordRecord}.
   *
   * @type {HostOf<LocalTransfer>}
   */
  const localTransfer = (srcSeat, localAccount, amounts) =>
    asVow(async () => {
      !srcSeat.hasExited() || Fail`The seat cannot have exited.`;
      const { zcfSeat: tempSeat, userSeat: userSeatP } = zcf.makeEmptySeatKit();
      const userSeat = await userSeatP;
      zcf.atomicRearrange(harden([[srcSeat, tempSeat, amounts]]));
      tempSeat.exit();
      // TODO (#9541) get the userSeat into baggage so it's at least recoverable
      // const userSeat = await subzone.makeOnce(
      //   'localTransferHelper',
      //   async () => {
      //     const { zcfSeat: tempSeat, userSeat: userSeatP } =
      //       zcf.makeEmptySeatKit();
      //     const uSeat = await userSeatP;
      //     // TODO how do I store in the place for this retryable?
      //     atomicTransfer(zcf, srcSeat, tempSeat, amounts);
      //     tempSeat.exit();
      //     return uSeat;
      //   },
      // );

      // Now all the `amounts` are accessible, so we can move them to the localAccount
      const payments = await Promise.all(
        keys(amounts).map(kw => E(userSeat).getPayout(kw)),
      );
      const settleDeposits = await when(
        allSettled(payments.map(pmt => E(localAccount).deposit(pmt))),
      );
      // if any of the deposits to localAccount failed, unwind all of the allocations
      if (settleDeposits.find(x => x.status === 'rejected')) {
        const amts = values(amounts);
        const errors = [];
        // withdraw the successfully deposited payments
        const paymentsOrWithdrawVs = settleDeposits.map((x, i) => {
          if (x.status === 'rejected') {
            errors.push(x.reason);
            return payments[i];
          }
          return E(localAccount).withdraw(amts[i]);
        });

        // return all payments to the srcSeat
        const paymentsToReturn = await when(allVows(paymentsOrWithdrawVs));
        const paymentKwr = harden(
          keys(amounts).reduce(
            (kwr, kw, i) => assign(kwr, { [kw]: paymentsToReturn[i] }),
            {},
          ),
        );
        const depositResponse = await depositToSeat(
          zcf,
          srcSeat,
          amounts,
          paymentKwr,
        );
        trace('localTransfer depositResponse', depositResponse);
        throw makeError(`One or more deposits failed ${q(errors)}`);
      }
      // TODO #9541 remove userSeat from baggage
    });

  /**
   * Transfer the `amounts` from a `localAccount` to the `recipientSeat`. If any
   * of the withdrawals fail, everything will be rolled back to the
   * `srcLocalAccount`. Supports multiple items in the `amounts`
   * {@link PaymentKeywordRecord}
   *
   * @type {HostOf<WithdrawToSeat>}
   */
  const withdrawToSeat = (localAccount, destSeat, amounts) =>
    asVow(async () => {
      !destSeat.hasExited() || Fail`The seat cannot have exited.`;

      const settledWithdrawals = await when(
        allSettled(values(amounts).map(amt => E(localAccount).withdraw(amt))),
      );

      // if any of the withdrawals were rejected, unwind the successful ones
      if (settledWithdrawals.find(x => x.status === 'rejected')) {
        const returnPaymentVs = [];
        const errors = [];
        for (const result of settledWithdrawals) {
          if (result.status === 'fulfilled') {
            returnPaymentVs.push(E(localAccount).deposit(result.value));
          } else {
            errors.push(result.reason);
          }
        }
        await when(allVows(returnPaymentVs));
        throw makeError(`One or more withdrawals failed ${q(errors)}`);
      }

      // successfully withdrew payments from srcLocalAccount, deposit to recipientSeat
      const fulfilledWithdrawals =
        /** @type {PromiseFulfilledResult<Payment>[]} */ (settledWithdrawals);
      const paymentKwr = harden(
        keys(amounts).reduce(
          (acc, kw, i) =>
            assign(acc, {
              [kw]: fulfilledWithdrawals[i].value,
            }),
          {},
        ),
      );
      const depositResponse = await depositToSeat(
        zcf,
        destSeat,
        amounts,
        paymentKwr,
      );
      trace('withdrawToSeat depositResponse', depositResponse);
