const bundleCache = await unsafeSharedBundleCache;
const { zcfBundle } = await bundleCache.loadRegistry(zoeSourceSpecRegistry);

// this simulates a bundlecap, which is normally a swingset "device node"
/** @type {() => BundleCap} */
const fakeBundleCap = () => makeHandle('FakeBundleCap');
const bogusBundleCap = () => makeHandle('BogusBundleCap');
export const zcfBundleCap = fakeBundleCap();

/**
 * @param {(...args) => unknown} [testContextSetter]
 * @param {(x: unknown) => unknown} [makeRemote]
 */
function makeFakeVatAdmin(testContextSetter = undefined, makeRemote = x => x) {
  // FakeVatPowers isn't intended to support testing of vat termination, it is
  // provided to allow unit testing of contracts that call zcf.shutdown()
  let exitMessage;
  let hasExited = false;
  let exitWithFailure;
  /** @type {MapStore<BundleID, BundleCap>} */
  const idToBundleCap = makeScalarMapStore('idToBundleCap');
  /** @type {Map<BundleCap, EndoZipBase64Bundle | {moduleFormat: 'test'}>} */
  const bundleCapToBundle = new Map();
  /** @type {MapStore<string, BundleID>} */
  const nameToBundleID = makeScalarMapStore('nameToBundleID');
  const fakeVatPowers = {
    exitVatWithFailure: reason => {
      exitMessage = reason;
      hasExited = true;
      exitWithFailure = true;
    },
    D: bundleCap => ({
      getBundle: () => bundleCapToBundle.get(bundleCap),
    }),
    testJigSetter: testContextSetter,
  };

  // This is explicitly intended to be mutable so that
  // test-only state can be provided from contracts
  // to their tests.
  const admin = Far('vatAdmin', {
    getBundleCap: bundleID => {
      if (!idToBundleCap.has(bundleID)) {
        idToBundleCap.init(bundleID, bogusBundleCap());
      }
      return Promise.resolve(idToBundleCap.get(bundleID));
    },
    waitForBundleCap: bundleID => {
      if (!idToBundleCap.has(bundleID)) {
        idToBundleCap.init(bundleID, bogusBundleCap());
      }
      return Promise.resolve(idToBundleCap.get(bundleID));
    },
    getNamedBundleCap: name => {
      if (name === 'zcf') {
        return Promise.resolve(zcfBundleCap);
      }
      const id = nameToBundleID.get(name);
      return Promise.resolve(idToBundleCap.get(id));
    },
    getBundleIDByName: name => {
      return Promise.resolve().then(() => nameToBundleID.get(name));
    },
    createVat: (bundleCap, { vatParameters = {} } = {}) => {
      bundleCap === zcfBundleCap || Fail`fakeVatAdmin only knows ZCF`;
      const exitKit = makePromiseKit();
      handlePKitWarning(exitKit);
      const exitVat = completion => {
        exitMessage = completion;
        hasExited = true;
        exitWithFailure = false;
        exitKit.resolve(completion);
      };
      const vpow = harden({
        ...fakeVatPowers,
        exitVat,
      });
      const vatBaggage = makeScalarBigMapStore('fake vat baggage', {
        durable: true,
      });

      // XXX Notice that this call isn't wrapping vatParams.  We (BW, CH) tried
      // doing this, but backed out when it got complex.
      //
      // const ns = await evalContractBundle(zcfBundle);
      // const ns2 = makeRemote(
      //   Far('wrappedRoot', {
      //     buildRootObject: vp => ns.buildRootObject(vpow, vp, vatBaggage),
      //   }),
      // );
      const rootP = makeRemote(
        E(evalContractBundle(zcfBundle)).buildRootObject(
          vpow,
          vatParameters,
          vatBaggage,
        ),
      );
      return E.when(rootP, root =>
        harden({
          root,
          adminNode: Far('adminNode', {
            done: () => {
              return exitKit.promise;
            },
            terminateWithFailure: () => {},
            upgrade: (_bundleCap, _options) => Fail`upgrade not faked`,
          }),
        }),
      );
    },
  });
  const criticalVatKey = harden({});
  const vatPowers = harden({
    D: bcap => {
      const bundle = bundleCapToBundle.get(bcap);
      bundle || Fail`fake D only does fake bundlecaps`;
      return harden({ getBundle: () => bundle });
    },
  });
  const vatAdminState = {
    getExitMessage: () => exitMessage,
    getHasExited: () => hasExited,
    getExitWithFailure: () => exitWithFailure,
    /**
     * @param {string} base
     * @param {EndoZipBase64Bundle | TestBundle} bundle
     */
    getBundleID: (base, bundle) => {
      if (bundle.moduleFormat !== 'endoZipBase64') {
        return base;
      }
      if (base === `b1-${bundle.endoZipBase64Sha512}`) {
        return base;
      }
      return `${base}-${bundle.endoZipBase64Sha512}`;
    },
    /**
     * @param {string} base
     * @param {EndoZipBase64Bundle | TestBundle} bundle
     */
    registerBundle: (base, bundle) => {
      const bid = vatAdminState.getBundleID(base, bundle);
      vatAdminState.installBundle(bid, bundle);
      return bid;
    },
    /**
     * @param {string} id
     * @param {EndoZipBase64Bundle | TestBundle} bundle
     */
    installBundle: (id, bundle) => {
      if (idToBundleCap.has(id)) {
        const extant = bundleCapToBundle.get(idToBundleCap.get(id));
        assert(extant);
        assert.equal(bundle.moduleFormat, extant.moduleFormat);
        if (extant.moduleFormat === 'endoZipBase64') {
          // Narrow bundle.moduleFormat now that extant.moduleFormat is narrowed
          assert.equal(bundle.moduleFormat, extant.moduleFormat);
          // Make the error message managable by only showing the length,
          // beginning and end of the huge base64 strings.
          const summarize = s =>
            `${s.length} chars (${s.slice(0, 10)}...${s.slice(-10)})`;
          assert(
            bundle.endoZipBase64 === extant.endoZipBase64,
            `bundle ${id} ${summarize(bundle.endoZipBase64)} differs from extant ${summarize(extant.endoZipBase64)}`,
          );
        }
        return idToBundleCap.get(id);
      }
      const bundleCap = fakeBundleCap();
      idToBundleCap.init(id, bundleCap);
      bundleCapToBundle.set(bundleCap, bundle);
      return bundleCap;
    },
    installNamedBundle: (name, id, bundle) => {
      nameToBundleID.init(name, id);
      return vatAdminState.installBundle(id, bundle);
    },
    getCriticalVatKey: () => criticalVatKey,
    getVatPowers: () => vatPowers,
  };
  return { admin, vatAdminState };
}

// Tests which use this global/shared fakeVatAdmin should really import
// makeFakeVatAdmin() instead, and build their own private instance. This
// will be forced when #4565 requires them to use
// vatAdminState.installBundle().

const fakeVatAdmin = makeFakeVatAdmin().admin;

/** @file Localchain Facade exo */
import { E } from '@endo/far';
// eslint-disable-next-line no-restricted-syntax -- just the import
import { heapVowE } from '@agoric/vow/vat.js';
import { M } from '@endo/patterns';
import { pickFacet } from '@agoric/vat-data';
import { VowShape } from '@agoric/vow';

import { chainFacadeMethods, TypedJsonShape } from '../typeGuards.js';

/**
 * @import {HostOf} from '@agoric/async-flow';
 * @import {Zone} from '@agoric/base-zone';
 * @import {TimerService} from '@agoric/time';
 * @import {Remote} from '@agoric/internal';
 * @import {LocalChain, LocalChainAccount, QueryManyFn} from '@agoric/vats/src/localchain.js';
 * @import {AssetInfo} from '@agoric/vats/src/vat-bank.js';
 * @import {NameHub} from '@agoric/vats';
 * @import {Vow, VowTools} from '@agoric/vow';
 * @import {CosmosInterchainService} from './exo-interfaces.js';
 * @import {LocalOrchestrationAccountKit, MakeLocalOrchestrationAccountKit} from './local-orchestration-account.js';
 * @import {Chain, CosmosChainAddress, ChainInfo, CosmosChainInfo, IBCConnectionInfo, OrchestrationAccount, OrchestrationOptions} from '../types.js';
 * @import {StorageNode} from '@agoric/internal/src/lib-chainStorage.js';
 */

/**
 * Chain facade methods unique to the Agoric (local) chain.
 *
 * @typedef {object} AgoricChainMethods
 * @property {() => Promise<AssetInfo[]>} getVBankAssetInfo Get asset info from
 *   agoricNames.vbankAsset.
 *
 *   Caches the query to agoricNames in the first call.
 */

/**
 * @typedef {{
 *   makeLocalOrchestrationAccountKit: MakeLocalOrchestrationAccountKit;
 *   orchestration: Remote<CosmosInterchainService>;
 *   storageNode: Remote<StorageNode> | undefined;
 *   agoricNames: Remote<NameHub>;
 *   timer: Remote<TimerService>;
 *   localchain: Remote<LocalChain>;
 *   vowTools: VowTools;
 * }} LocalChainFacadePowers
 */

/**
 * @param {Zone} zone
 * @param {LocalChainFacadePowers} powers
 */
const prepareLocalChainFacadeKit = (
  zone,
  {
    makeLocalOrchestrationAccountKit,
    agoricNames,
    localchain,
    // TODO vstorage design https://github.com/Agoric/agoric-sdk/issues/9066
    // consider making an `accounts` childNode
    storageNode,
    vowTools: { allVows, watch, asVow },
  },
) =>
  zone.exoClassKit(
    'LocalChainFacade',
    {
      public: M.interface('LocalChainFacade', {
        ...chainFacadeMethods,
        query: M.call(M.arrayOf(TypedJsonShape)).returns(VowShape),
        getVBankAssetInfo: M.call().optional(M.boolean()).returns(VowShape),
      }),
      vbankAssetValuesWatcher: M.interface('vbankAssetValuesWatcher', {
        onFulfilled: M.call(M.arrayOf(M.record()))
          .optional(M.arrayOf(M.undefined())) // empty context
          .returns(VowShape),
      }),
      makeAccountWatcher: M.interface('makeAccountWatcher', {
        onFulfilled: M.call([M.remotable('LCA Account'), M.string()])
          .optional(M.arrayOf(M.undefined())) // empty context
          .returns(VowShape),
      }),
      makeChildNodeWatcher: M.interface('makeChildNodeWatcher', {
        onFulfilled: M.call(M.or(M.remotable(), M.undefined()))
          .optional({ account: M.remotable(), address: M.string() }) // empty context
          .returns(M.remotable()),
      }),
    },
    /**
     * @param {CosmosChainInfo} localChainInfo
     */
    localChainInfo => {
      return {
        localChainInfo,
        vbankAssets: /** @type {AssetInfo[] | undefined} */ (undefined),
      };
    },
    {
      public: {
        /** @type {HostOf<Chain['getChainInfo']>} */
        getChainInfo() {
          return watch(this.state.localChainInfo);
        },

        /** @type {HostOf<Chain['makeAccount']>} */
        makeAccount() {
          const lcaP = E(localchain).makeAccount();
          return watch(
            // XXX makeAccount returns a Promise for an exo but reserves being able to return a vow
            // so we use heapVowE to shorten the promise path
            // eslint-disable-next-line no-restricted-syntax -- will run in one turn
            allVows([lcaP, heapVowE(lcaP).getAddress()]),
            this.facets.makeAccountWatcher,
          );
        },
        /** @type {HostOf<Chain<{ chainId: 'agoriclocal' }>['query']>} */
        query(requests) {
          return watch(E(localchain).queryMany(requests));
        },
        /** @type {HostOf<AgoricChainMethods['getVBankAssetInfo']>} */
        getVBankAssetInfo() {
          return asVow(() => {
            const { vbankAssets } = this.state;
            if (vbankAssets) {
              return vbankAssets;
            }
            const vbankAssetNameHubP = E(agoricNames).lookup('vbankAsset');
            const vbankAssetValuesP = E(vbankAssetNameHubP).values();
            const { vbankAssetValuesWatcher } = this.facets;
            return watch(vbankAssetValuesP, vbankAssetValuesWatcher);
          });
        },
      },
      vbankAssetValuesWatcher: {
        /**
         * @param {AssetInfo[]} assets
         */
        onFulfilled(assets) {
          const { state } = this;
          return asVow(() => {
            state.vbankAssets = assets;
            return assets;
          });
        },
      },
      makeAccountWatcher: {
        /**
         * @param {[LocalChainAccount, CosmosChainAddress['value']]} results
         */
        onFulfilled([account, address]) {
          const optionalStorageNode = storageNode
            ? E(storageNode).makeChildNode(address)
            : undefined;
          return watch(optionalStorageNode, this.facets.makeChildNodeWatcher, {
            account,
            address,
          });
        },
      },
      makeChildNodeWatcher: {
        /**
         * @param {Remote<StorageNode>} childNode
         * @param {{
         *   account: LocalChainAccount;
         *   address: CosmosChainAddress['value'];
         * }} ctx
         */
        onFulfilled(childNode, { account, address }) {
          const { localChainInfo } = this.state;
          const { holder } = makeLocalOrchestrationAccountKit({
            account,
            address: harden({
              value: address,
              encoding: 'bech32',
              chainId: localChainInfo.chainId,
            }),
            // FIXME storage path https://github.com/Agoric/agoric-sdk/issues/9066
            storageNode: childNode,
          });
          return holder;
        },
      },
    },
  );
harden(prepareLocalChainFacadeKit);

/**
 * Used only by `withOrchestration` helper
 *
 * @param {Zone} zone
 * @param {LocalChainFacadePowers} powers
 * @internal
 */
export const prepareLocalChainFacade = (zone, powers) => {
  const makeLocalChainFacadeKit = prepareLocalChainFacadeKit(zone, powers);
  return pickFacet(makeLocalChainFacadeKit, 'public');
};
harden(prepareLocalChainFacade);

/** @typedef {ReturnType<typeof prepareLocalChainFacade>} MakeLocalChainFacade */
/** @typedef {ReturnType<MakeLocalChainFacade>} LocalChainFacade */
/** @file Remote Chain Facade exo */
import { makeTracer } from '@agoric/internal';
import { E } from '@endo/far';
import { Fail, q } from '@endo/errors';
import { M } from '@endo/patterns';
import { pickFacet } from '@agoric/vat-data';
import { VowShape } from '@agoric/vow';
import {
  CosmosChainAddressShape,
  chainFacadeMethods,
  ICQMsgShape,
} from '../typeGuards.js';

/**
 * @import {HostOf} from '@agoric/async-flow';
 * @import {Zone} from '@agoric/base-zone';
 * @import {JsonSafe} from '@agoric/cosmic-proto';
 * @import {RequestQuery, ResponseQuery} from '@agoric/cosmic-proto/tendermint/abci/types.js';
 * @import {TimerService} from '@agoric/time';
 * @import {Remote} from '@agoric/internal';
 * @import {Vow, VowTools} from '@agoric/vow';
 * @import {
 *   IBCConnectionInfo,
 *   LocalIbcAddress,
 *   RemoteIbcAddress,
 * } from '@agoric/network/ibc';
 * @import {CosmosInterchainService} from './exo-interfaces.js';
 * @import {prepareCosmosOrchestrationAccount} from './cosmos-orchestration-account.js';
 * @import {CosmosChainInfo, CosmosChainAddress, IcaAccount, Chain, ICQConnection, ChainInfo} from '../types.js';
 * @import {StorageNode} from '@agoric/internal/src/lib-chainStorage.js';
 */

const trace = makeTracer('RemoteChainFacade');

/**
 * @typedef {{
 *   makeCosmosOrchestrationAccount: ReturnType<
 *     typeof prepareCosmosOrchestrationAccount
 *   >;
 *   orchestration: Remote<CosmosInterchainService>;
 *   storageNode: Remote<StorageNode> | undefined;
 *   timer: Remote<TimerService>;
 *   vowTools: VowTools;
 * }} RemoteChainFacadePowers
 */

/**
 * @typedef {{
 *   remoteChainInfo: ChainInfo;
 *   connectionInfo: IBCConnectionInfo | undefined;
 *   icqConnection: ICQConnection | undefined;
 * }} RemoteChainFacadeState
 */

/**
 * @param {Zone} zone
 * @param {RemoteChainFacadePowers} powers
 */
const prepareRemoteChainFacadeKit = (
  zone,
  {
    makeCosmosOrchestrationAccount,
    orchestration,
    // TODO vstorage design https://github.com/Agoric/agoric-sdk/issues/9066
    // consider making an `accounts` childNode
    storageNode,
    timer,
    vowTools: { allVows, asVow, watch },
  },
) =>
  zone.exoClassKit(
    'RemoteChainFacade',
    {
      public: M.interface('RemoteChainFacade', {
        ...chainFacadeMethods,
        query: M.call(M.arrayOf(ICQMsgShape)).returns(VowShape),
      }),
      makeICQConnectionQueryWatcher: M.interface(
        'makeICQConnectionQueryWatcher',
        {
          onFulfilled: M.call(M.remotable(), M.arrayOf(ICQMsgShape)).returns(
            VowShape,
          ),
        },
      ),
      makeAccountAndProvideQueryConnWatcher: M.interface(
        'makeAccountAndProvideQueryConnWatcher',
        {
          onFulfilled: M.call([
            M.remotable(),
            M.or(M.remotable(), M.undefined()),
          ]).returns(VowShape),
        },
      ),
      getAddressesWatcher: M.interface('getAddressWatcher', {
        onFulfilled: M.call(
          [CosmosChainAddressShape, M.string(), M.string()],
          M.remotable(),
        ).returns(VowShape),
      }),
      makeChildNodeWatcher: M.interface('makeChildNodeWatcher', {
        onFulfilled: M.call(M.or(M.remotable(), M.undefined()), {
          account: M.remotable(),
          chainAddress: CosmosChainAddressShape,
          localAddress: M.string(),
          remoteAddress: M.string(),
        }).returns(M.remotable()),
      }),
    },
    /**
     * @param {ChainInfo} remoteChainInfo
     * @param {IBCConnectionInfo} [connectionInfo]
     */
    (remoteChainInfo, connectionInfo) => {
      trace('making a RemoteChainFacade');
      return /** @type {RemoteChainFacadeState} */ ({
        remoteChainInfo,
        connectionInfo,
        icqConnection: undefined,
      });
    },
    {
      public: {
        /** @type {HostOf<Chain['getChainInfo']>} */
        getChainInfo() {
          return watch(this.state.remoteChainInfo);
        },

        /** @type {HostOf<Chain['makeAccount']>} */
        makeAccount() {
          return asVow(() => {
            const { remoteChainInfo, connectionInfo } = this.state;

            if (remoteChainInfo.namespace !== 'cosmos') {
              throw Fail`only supported on 'cosmos' chains, not ${remoteChainInfo.namespace}`;
            }
            if (!connectionInfo) throw Fail`IBC connection info not found`;

            // icqConnection is ultimately retrieved from state, but let's
            // create a connection if it doesn't exist
            const icqConnOrUndefinedV =
              /** @type {CosmosChainInfo} */ (remoteChainInfo)?.icqEnabled &&
              !this.state.icqConnection
                ? E(orchestration).provideICQConnection(connectionInfo.id)
                : undefined;

            const makeAccountV = E(orchestration).makeAccount(
              /** @type {CosmosChainInfo} */ (remoteChainInfo).chainId,
              connectionInfo.counterparty.connection_id,
              connectionInfo.id,
            );

            return watch(
              allVows([makeAccountV, icqConnOrUndefinedV]),
              this.facets.makeAccountAndProvideQueryConnWatcher,
            );
          });
        },
        /**
         * @type {HostOf<
         *   Chain<CosmosChainInfo & { icqEnabled: true }>['query']
         * >}
         */
        query(msgs) {
          return asVow(() => {
            /**
             * @typedef {{
             *   remoteChainInfo: CosmosChainInfo;
             *   connectionInfo?: IBCConnectionInfo;
             * }} QueryState
             */
            const {
              remoteChainInfo: { icqEnabled, chainId },
              connectionInfo,
            } = /** @type {QueryState} */ (this.state);

            if (!icqEnabled) {
              throw Fail`Queries not available for chain ${q(chainId)}`;
            }
            if (!connectionInfo) throw Fail`IBC connection info not found`;
            // if none exists, make one and still send the query in the handler
            if (!this.state.icqConnection) {
              return watch(
                E(orchestration).provideICQConnection(connectionInfo.id),
                this.facets.makeICQConnectionQueryWatcher,
                msgs,
              );
            }
            return watch(E(this.state.icqConnection).query(msgs));
          });
        },
      },
      makeAccountAndProvideQueryConnWatcher: {
        /**
         * @param {[IcaAccount, ICQConnection | undefined]} account
         */
        onFulfilled([account, icqConnection]) {
          if (icqConnection && !this.state.icqConnection) {
            this.state.icqConnection = icqConnection;
            // no need to pass icqConnection in ctx; we can get it from state
          }
          return watch(
            allVows([
              E(account).getAddress(),
              E(account).getLocalAddress(),
              E(account).getRemoteAddress(),
            ]),
            this.facets.getAddressesWatcher,
            account,
          );
        },
      },
      makeICQConnectionQueryWatcher: {
        /**
         * @param {ICQConnection} icqConnection
         * @param {JsonSafe<RequestQuery>[]} msgs
         * @returns {Vow<JsonSafe<ResponseQuery>[]>}
         */
        onFulfilled(icqConnection, msgs) {
          if (!this.state.icqConnection) {
            this.state.icqConnection = icqConnection;
          }
          return watch(E(icqConnection).query(msgs));
        },
      },
      getAddressesWatcher: {
        /**
         * @param {[CosmosChainAddress, LocalIbcAddress, RemoteIbcAddress]} chainAddresses
         * @param {IcaAccount} account
         */
        onFulfilled([chainAddress, localAddress, remoteAddress], account) {
          const optionalStorageNode = storageNode
            ? E(storageNode).makeChildNode(chainAddress.value)
            : undefined;
          return watch(optionalStorageNode, this.facets.makeChildNodeWatcher, {
            account,
            chainAddress,
            localAddress,
            remoteAddress,
          });
        },
      },
      makeChildNodeWatcher: {
        /**
         * @param {Remote<StorageNode> | undefined} childNode
         * @param {{
         *   account: IcaAccount;
         *   chainAddress: CosmosChainAddress;
         *   localAddress: LocalIbcAddress;
         *   remoteAddress: RemoteIbcAddress;
         * }} ctx
         */
        onFulfilled(
          childNode,
          { account, chainAddress, localAddress, remoteAddress },
        ) {
          const { icqConnection } = this.state;

          return makeCosmosOrchestrationAccount(
            {
              chainAddress,
              localAddress,
              remoteAddress,
            },
            {
              account,
              // FIXME storage path https://github.com/Agoric/agoric-sdk/issues/9066
              storageNode: childNode,
              icqConnection,
              timer,
            },
          );
        },
      },
    },
  );
harden(prepareRemoteChainFacadeKit);

/**
 * @param {Zone} zone
 * @param {RemoteChainFacadePowers} powers
 */
export const prepareRemoteChainFacade = (zone, powers) => {
  const makeLocalChainFacadeKit = prepareRemoteChainFacadeKit(zone, powers);
  return pickFacet(makeLocalChainFacadeKit, 'public');
};
harden(prepareRemoteChainFacade);

/** @typedef {ReturnType<typeof prepareRemoteChainFacade>} MakeRemoteChainFacade */
/** @typedef {ReturnType<MakeRemoteChainFacade>} RemoteChainFacade */

import { E, makeLoopback } from '@endo/captp';

import { makeScalarBigMapStore } from '@agoric/vat-data';
import bundleSource from '@endo/bundle-source';
import { bundleTestExports } from '@endo/import-bundle';
import { makeDurableZoeKit } from '../src/zoeService/zoe.js';
import fakeVatAdmin, { makeFakeVatAdmin } from './fakeVatAdmin.js';

/**
 * @import {EndoZipBase64Bundle, TestBundle, VatAdminSvc} from '@agoric/swingset-vat';
 * @import {FeeIssuerConfig, Installation} from '../src/types-index.js';
 */

/**
 * @param {VatAdminSvc} [vatAdminSvc]
 */
export const makeZoeKitForTest = (vatAdminSvc = fakeVatAdmin) => {
  return makeDurableZoeKit({
    vatAdminSvc,
    zoeBaggage: makeScalarBigMapStore('zoe baggage', { durable: true }),
  });
};

/**
 * @param {VatAdminSvc} [vatAdminSvc]
 */
export const makeZoeForTest = vatAdminSvc =>
  makeZoeKitForTest(vatAdminSvc).zoeService;

/**
 * Returns promises for `zoe` and the `feeMintAccess`.
 * Provide testing versions of capabilities for Zoe contracts.
 *
 * @template {object} [T=any]
 * @param {object} options
 * @param {(jig: T) => void} [options.setJig]
 * @param {FeeIssuerConfig} [options.feeIssuerConfig]
 * @param {VatAdminSvc} [options.vatAdminSvc]
 * @param {boolean} [options.useNearRemote]
 */
export const setUpZoeForTest = async ({
  setJig = () => {},
  feeIssuerConfig,
  vatAdminSvc,
  useNearRemote = false,
} = {}) => {
  const { makeFar, makeNear } = makeLoopback('zoeTest');

  /** @type {ReturnType<typeof makeFakeVatAdmin>['vatAdminState'] | undefined} */
  let vatAdminState;
  if (!vatAdminSvc) {
    ({ admin: vatAdminSvc, vatAdminState } = makeFakeVatAdmin(
      setJig,
      useNearRemote ? makeNear : undefined,
    ));
  }
  const { zoeService, feeMintAccess } = await makeFar(
    makeDurableZoeKit({
      vatAdminSvc,
      feeIssuerConfig,
      zoeBaggage: makeScalarBigMapStore('zoe baggage', { durable: true }),
    }),
  );

  /**
   * @param {object} pathOrExports
   * @returns {Promise<EndoZipBase64Bundle | TestBundle>}
   */
